+        <p class="error-message" id="fullNameError" aria-live="polite"></p>
+      </div>
+
+      <div class="form-field">
+        <label for="email">Email address</label>
+        <input
+          type="email"
+          id="email"
+          name="email"
+          placeholder="alex@example.com"
+          autocomplete="email"
+          aria-describedby="emailError"
+          required
+        >
+        <p class="error-message" id="emailError" aria-live="polite"></p>
+      </div>
+
+      <div class="form-field">
+        <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
+        <input
+          type="tel"
