+          (field) => field.input.getAttribute("aria-invalid") === "true"
+        );
+        firstInvalidField.input.focus();
+        return;
+      }
+
+      formStatus.textContent = "Thanks! Your support request is ready to send.";
+      form.reset();
+      Object.values(fields).forEach((field) => setFieldError(field, ""));
+    });
+  </script>
+</body>
+</html>
