        >
        <p class="error-message" id="emailError" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
        <input
          type="tel"
          id="phone"
          name="phone"
          placeholder="+1 555 123 4567"
          autocomplete="tel"
          aria-describedby="phoneHelp phoneError"
        >
        <p class="helper-text" id="phoneHelp">Expected format: include digits, spaces, dashes, parentheses, or an optional leading +, such as +1 555 123 4567.</p>
        <p class="error-message" id="phoneError" aria-live="polite"></p>
      </div>

      <button type="submit">Submit support request</button>
      <p class="form-status" id="formStatus" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.querySelector("#supportForm");
    const fields = {
      fullName: {
        input: document.querySelector("#fullName"),
        error: document.querySelector("#fullNameError"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }

          if (value.trim().length < 2) {
            return "Enter your full name.";
          }

          return "";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#emailError"),
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }

          return "";
