        validate(value) {
          const trimmedValue = value.trim();

          if (!trimmedValue) {
            return "";
          }

          const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
          if (!phonePattern.test(trimmedValue)) {
            return "Enter a valid phone number or leave this field blank.";
          }

          return "";
        }
      }
    };

